using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    /// <summary>Returns application configuration as JSON.</summary>
    [McpServerResource(UriTemplate = "config://app", Name = "app-config",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new { Logging = true, Caching = true, RateLimiting = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns configuration for a named environment.</summary>
    [McpServerResource(UriTemplate = "config://env/{environment}", Name = "env-config",
        MimeType = "application/json")]
    public static string GetEnvironmentConfig(string environment)
    {
        var config = environment.ToLowerInvariant() switch
        {
            "production" => new { LogLevel = "Warning", Debug = false, Replicas = 3 },
            "staging"    => new { LogLevel = "Information", Debug = false, Replicas = 1 },
            _            => new { LogLevel = "Debug", Debug = true, Replicas = 1 }
        };

        return JsonSerializer.Serialize(new { Environment = environment, Settings = config },
            new JsonSerializerOptions { WriteIndented = true });
    }
}

